    "text": "Additives are non-hydrocarbon compounds added to or blended with a petroleum products to modify their properties (octane, cetane, cold properties, etc.). Additives include oxygenates (such as alcohols (methanol, ethanol), ethers (methyl tertiary butyl ether(MTBE), ethyl tertiary butyl ether (ETBE), tertiary amyl methyl ether (TAME), etc.), esters (such as rapeseed oil or dimethylester, etc.), chemical compounds (such as tetramethyl lead (TML), tetraethyl lead (TEL) and detergents).Quantities of additives/oxygenates (alcohols, ethers, esters and other chemical compounds) reported in this category should relate to the quantities blended with fuels or for fuel use. This category includes biofuels that are blended with liquid fossil fuels.",
