    "text": "Motor gasoline consists of a mixture of light hydrocarbons distilling at between 35 °C and 215 °C. It is used as a fuel for land-based spark ignition engines. Motor gasoline may include additives, oxygenates and octane enhancers, including lead compounds. Includes motor gasoline blending components (excluding additives/oxygenates), e.g. alkylates, isomerate, reformate, cracked gasoline destined for use as finished motor gasoline. Motor gasoline is a product aggregate equal to the sum of blended biogasoline (biogasoline in motor gasoline) and non-biogasoline.",
