    "text": "Distillate used for aviation turbine power units. It has the same distillation characteristics at between 150 °C and 300 °C (generally not above 250 °C) and flash point as kerosene. In addition, it has particular specifications (such as freezing point) which are established by the International Air Transport Association. Includes kerosene blending components. Kerosene type jet fuel is a product aggregate equal to the sum of blended bio jet kerosene (bio jet kerosene in kerosene type jet fuel) and non-bio jet kerosene.",
