    "text": "total of all products, the Total energy supply  is one of the most important aggregate of energy balance and represents the quantity of energy necessary to satisfy inland consumption (inland fuel deliveries) of the geographical entity under consideration.\nIts interpretation for individual products is analogical. For secondary products, which are produced as transformation output and not as primary productions, the Total energy supply can be negative. This aggregate reflects on the recommendations in IRES for calculation of key aggregates of energy balances. ",
