    "title": "Transformation input - refineries and petrochemical industry - direct use - energy use",
    "text": "Crude oil, Natural gas liquids, Additives/Oxygenates and Other hydrocarbons which are used directly without being processed in petroleum refineries are reported as Direct use. These products disappear from their availability for further use in for Refineries & Petrochemical industry and appear as available products for the rest of the economy under Primary product receipts. The sum of reported Direct use in tons should equal to Primary product receipts in tons.",
