    "text": "Available for final consumption (aka Energy available for final consumption) is an aggregate calculated in the following way: Energy available for final consumption = + Total energy supply – Transformation input + Transformation output – Energy sector – Distribution losses. It represents the quantity of energy that was made available for final consumption. If it is negative, it indicates problems with data accuracy in reported energy statistics.",
