    "text": "Gross heat production: The blocks of energy balance matrix do not allow seeing heat generation from each specific fuel. Therefore the matrix is complemented by the rows that allow showing heat production from each fuel.\nNote: The total heat production by fuel can be lower than total transformation output due to category \"Other sources\". This category cannot be attributed to any specific fuel.\nGross heat production = + Main activity producer CHP + Main activity producer heat only + Autoproducer CHP + Autoproducer heat only\nAttention: Gross heat production is shown in the same energy units as the rest of the energy balance.",
