    "text": "Electricity generated by wind turbines located in bodies of water, typically in the ocean or sea. Offshore wind farms are built in marine environments where wind speeds are typically higher and more consistent than onshore locations, allowing for greater electricity generation potential. These installations are generally more expensive to build and maintain than onshore wind farms, but can generate more electricity due to stronger and more reliable wind conditions. They also benefit from reduced visual and noise impact compared to onshore installations.",
