    "title": "Crude oil, NGL, refinery feedstocks, additives and oxygenates and other hydrocarbons",
    "text": "This aggregate category encompasses all primary petroleum resources and inputs to refining processes. It includes crude oil (unprocessed petroleum extracted from the ground), natural gas liquids (liquid hydrocarbons recovered from natural gas processing), refinery feedstocks (processed oils destined for further refining), additives and oxygenates (compounds added to petroleum products to modify their properties), and other hydrocarbons (such as synthetic crude oil from tar sands and oil shale). Together, these components represent the full spectrum of hydrocarbon inputs that feed into petroleum refining and processing operations.",
