    "text": "Gas oils are middle distillates, predominantly of carbon number range C11 to C25 and with a distillation range of 160ºC to 420°C. The principal marketed products are fuels for diesel engines (diesel oil), heating oils and marine fuel. Gas oils are also used as middle distillate feedstock for the petrochemical industry and as solvents. Also included here is heavy gasoil, which is a mixture of predominantly gas oil and fuel oil which distills in the range of approximately 380ºC to 540ºC.",
