    "text": "The total energy required within a country's territorial boundaries to meet all consumption needs. This indicator represents the sum of energy used for transformation processes, energy industry's own consumption, distribution losses, and final consumption across all sectors of the economy. It provides a comprehensive measure of a country's total domestic energy requirements and is a key indicator for energy policy planning and analysis.",
